import { useCallback, useMemo } from "react";

const FIRST_FOLDER_TOP = 260; // Folder top - gap to make the code simpler.
const FOLDER_TAB_HEIGHT = 48;
const ROW_HEIGHT = 72;
const ROW_PADDING = 12;
const TOP_PADDING = 16;
const MIN_HEIGHT = 144;
const FOLDER_GAP = 20;
const BORDER = 2;

export type Style = {
  height: number | "auto";
  sticky: boolean;
  marginTop: number;
};

export type StyleCalculator = {
  getStyle: (index: number) => Style;
};

export type FolderInfo = {
  top: number;
  height: number;
};

export const useFolderHeights = (
  rounds: { rows: number }[],
): StyleCalculator => {
  const folderInfo = useMemo(() => {
    const folderInfos: FolderInfo[] = [];
    let bottom = FIRST_FOLDER_TOP;
    for (const folder of rounds) {
      const height =
        FOLDER_TAB_HEIGHT +
        BORDER +
        ROW_PADDING +
        folder.rows * (ROW_HEIGHT + ROW_PADDING);
      const top = bottom + FOLDER_GAP;
      bottom += FOLDER_GAP + height;
      folderInfos.push({
        top,
        height,
      });
    }

    return folderInfos;
  }, [rounds]);

  const getStyle = useCallback(
    (index: number) => {
      if (window.scrollY === undefined || folderInfo === undefined) {
        return {
          height: "auto" as const,
          sticky: false,
          marginTop: 0,
        };
      }

      let height: number | "auto";
      let sticky: boolean;
      let marginTop: number;

      const info = folderInfo[index];
      if (info === undefined) {
        throw new Error("Bug! Expected info to be defined");
      }

      if (window.scrollY < info.top - TOP_PADDING) {
        height = "auto";
        sticky = false;
        marginTop = 0;
      } else if (
        window.scrollY >= info.top - TOP_PADDING &&
        window.scrollY <= info.top - TOP_PADDING + info.height - MIN_HEIGHT - 2
      ) {
        height =
          info.height - (window.scrollY - info.top + TOP_PADDING) - BORDER;
        sticky = true;
        marginTop = info.height - height - BORDER;
      } else {
        height = MIN_HEIGHT;
        sticky = false;
        marginTop = info.height - height - BORDER;
      }

      return { sticky, height, marginTop };
    },
    [folderInfo],
  );

  return { getStyle };
};
