import { type TeamHuntState } from "@hunt/public-client";
import { FilterButton, PrimarySearchField } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { SearchIcon } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  type AllPuzzlesPuzzle,
  type AllPuzzlesRound,
  type AllPuzzlesState,
} from "../client/all_puzzles_types";
import PuzzleCard, {
  PuzzleIconFromState,
} from "./PuzzleAndTaskDisplay/PuzzleCard";
import { RoundFolder } from "./PuzzleAndTaskDisplay/RoundFolder";
import {
  type Style,
  useFolderHeights,
} from "./PuzzleAndTaskDisplay/useFolderHeights";
import { TeamStateProvider } from "./TeamStateProvider";

const LOCAL_STORAGE_KEYS = {
  showUnlockable: "all-puzzles-show-unlockable",
  showUnlocked: "all-puzzles-show-unlocked",
  showSolved: "all-puzzles-show-solved",
};

export const PuzzleRow = ({
  bolded,
  children,
}: {
  bolded?: boolean;
  children: React.ReactNode;
}) => {
  const rowClasses = `text-xl ${bolded ? "font-bold" : ""}`;
  return <div className={rowClasses}>{children}</div>;
};

const PuzzlesListForRound = ({ puzzles }: { puzzles: AllPuzzlesPuzzle[] }) => {
  return (
    <div className="w-full px-3 pb-3 flex flex-col gap-3">
      {puzzles.map((puz) => {
        return (
          <React.Fragment key={puz.slug}>
            {/* No outer card — render the PuzzleCard directly */}
            <PuzzleCard
              lockState={puz.state ?? "locked"}
              answer={puz.answer}
              title={puz.title}
              slug={puz.slug}
              round_slug={puz.round_slug}
              desc={puz.desc}
              unlock_cost={puz.unlock_cost}
              is_overworld_feeder={puz.is_overworld_feeder}
              nsfw={puz.nsfw}
              physicalPresenceRequirement={
                puz.physical_presence_requirement ?? undefined
              }
              meta={puz.is_meta ?? false}
              capstone={puz.is_capstone ?? false}
            />
          </React.Fragment>
        );
      })}
    </div>
  );
};

type AllPuzzlesRoundProps = {
  round: AllPuzzlesRound;
  index: number;
  getStyle: () => Style;
  state: AllPuzzlesState;
  teamState: TeamHuntState;
};

const AllPuzzlesRound = ({
  round,
  index,
  getStyle,
  state,
  teamState,
}: AllPuzzlesRoundProps) => {
  const count = round.puzzles.length;
  const isUnlocked = teamState.rounds[round.slug]?.locked === "unlocked";
  const roundLink =
    round.slug === "kingdom_of_the_puzzmon" ? "/" : `/rounds/${round.slug}`;

  return (
    <RoundFolder
      round={round}
      index={index}
      count={count}
      getStyle={getStyle}
      state={state}
      href={isUnlocked ? roundLink : undefined}
    >
      {round.puzzles.length > 0 ? (
        <PuzzlesListForRound puzzles={round.puzzles} />
      ) : (
        <div className="text-xl text-secondary font-semibold px-6 pb-4">
          {isUnlocked ? (
            <>
              Explore{" "}
              <a
                href={roundLink}
                className="underline text-secondary hover:text-accent-blue"
              >
                {round.title}
              </a>{" "}
              to discover puzzles!
            </>
          ) : (
            <>Unlock {round.title} to discover puzzles!</>
          )}
        </div>
      )}
    </RoundFolder>
  );
};

const PuzzlesList = ({
  state,
  allPuzzlesVisible,
  search,
  teamState,
}: {
  state: AllPuzzlesState;
  allPuzzlesVisible: boolean;
  search: string;
  teamState: TeamHuntState;
}) => {
  const visibleRounds = useMemo(() => {
    return state.rounds.filter((round) => {
      const count = round.puzzles.length;
      return (
        count > 0 ||
        (allPuzzlesVisible &&
          round.title.toLowerCase().includes(search.trim().toLowerCase()))
      );
    });
  }, [state.rounds, allPuzzlesVisible, search]);

  const { getStyle } = useFolderHeights(
    visibleRounds.map((round) => ({ rows: round.puzzles.length })),
  );

  return (
    <>
      {visibleRounds.map((round, i) => {
        return (
          <AllPuzzlesRound
            key={round.slug}
            round={round}
            index={i}
            getStyle={() => getStyle(i)}
            state={state}
            teamState={teamState}
          />
        );
      })}

      {/* If there are no results, show an informative message. */}
      {visibleRounds.length === 0 && (
        <span className="text-2xl mx-auto font-bold">No results found</span>
      )}
    </>
  );
};

export default function AllPuzzlesList({
  state,
  teamState,
}: {
  state: AllPuzzlesState;
  teamState: TeamHuntState;
}) {
  const [showUnlockable, setShowUnlockable] = useState(false);
  const [showUnlocked, setShowUnlocked] = useState(false);
  const [showSolved, setShowSolved] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    setShowUnlockable(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showUnlockable) === "true",
    );
    setShowUnlocked(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showUnlocked) === "true",
    );
    setShowSolved(
      localStorage.getItem(LOCAL_STORAGE_KEYS.showSolved) === "true",
    );
  }, []);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showUnlockable,
      JSON.stringify(showUnlockable),
    );
  }, [showUnlockable]);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showUnlocked,
      JSON.stringify(showUnlocked),
    );
  }, [showUnlocked]);

  useEffect(() => {
    localStorage.setItem(
      LOCAL_STORAGE_KEYS.showSolved,
      JSON.stringify(showSolved),
    );
  }, [showSolved]);

  const toggleShowUnlockable = useCallback(() => {
    setShowUnlockable((p) => !p);
  }, []);
  const toggleShowUnlocked = useCallback(() => {
    setShowUnlocked((p) => !p);
  }, []);
  const toggleShowSolved = useCallback(() => {
    setShowSolved((p) => !p);
  }, []);

  const filterPuzzle = useCallback(
    (puzzle: AllPuzzlesPuzzle) => {
      const q = search.trim().toLowerCase();

      // Text match: puzzle title OR round title
      if (q !== "") {
        if (q === "capstone" && puzzle.is_capstone) {
          return true;
        } else if (q === "meta" && puzzle.is_meta && !puzzle.is_capstone) {
          return true;
        }
        const inPuzzle = puzzle.title.toLowerCase().includes(q);
        let inRound = false;
        if (puzzle.round_slug) {
          const round = state.rounds.find((r) => r.slug === puzzle.round_slug);
          if (round?.title) {
            inRound = round.title.toLowerCase().includes(q);
          }
        }
        if (!inPuzzle && !inRound) return false;
      }

      // If all the filters are selected or all the filters are deselected, we want to show all puzzles.
      // We show the puzzles even if all the filters are deselected because the original filtering logic was unintuitive,
      // and there is virtually no case where you would want to deselect all the filters.
      let currShowSolved = showSolved;
      let currShowUnlocked = showUnlocked;
      let currShowUnlockable = showUnlockable;
      if (!showSolved && !showUnlocked && !showUnlockable) {
        currShowSolved = true;
        currShowUnlocked = true;
        currShowUnlockable = true;
      }

      // Status filters
      if (puzzle.answer !== undefined) return currShowSolved;
      if (puzzle.state === "unlocked") return currShowUnlocked;
      if (puzzle.state === "unlockable") {
        if (puzzle.hide_unlockable) {
          return false;
        }
        return currShowUnlockable;
      }
      return true;
    },
    [showSolved, showUnlocked, showUnlockable, search, state.rounds],
  );

  const filteredState = useMemo(() => {
    // First, filter puzzles within each round
    const filteredRounds = state.rounds
      .map((round) => {
        const filteredPuzzles = round.puzzles.filter((p) => filterPuzzle(p));
        return { ...round, puzzles: filteredPuzzles };
      })
      .filter((round) => {
        // Hide any other rounds that now have zero puzzles and are not an overworld round.
        if (round.puzzles.length === 0 && !round.is_overworld_round) {
          return false;
        }
        // For overworld rounds, only hide if the search term doesn't match the round title.
        if (
          round.puzzles.length === 0 &&
          !round.title.toLowerCase().includes(search.trim().toLowerCase())
        ) {
          return false;
        }
        // Otherwise, show the round in the list.
        return true;
      });

    return { ...state, rounds: filteredRounds };
  }, [state, filterPuzzle, search]);

  return (
    <TeamStateProvider teamState={teamState}>
      <div className="flex flex-col gap-5">
        {/* Search + Filters */}
        <div className="flex flex-col gap-2">
          <PrimarySearchField
            name="search-all-puzzles"
            value={search}
            onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
              setSearch(e.target.value);
            }}
            placeholder="Search puzzles by title, round, or tag…"
            aria-label="Search puzzles by title, round, or tag"
            leftIcon={SearchIcon}
          />
          <div className="flex gap-4 space-between">
            <FilterButton
              selected={showUnlockable}
              onClick={toggleShowUnlockable}
              icon={
                <PuzzleIconFromState
                  state="unlockable"
                  className="text-gray-400 group-hover/filter-button:text-white group-focus-visible/filter-button:text-white group-data-[selected=true]/filter-button:text-accent-blue"
                />
              }
              className={cn("w-full", !showUnlockable && "text-gray-400")}
            >
              LOCKED
            </FilterButton>
            <FilterButton
              selected={showUnlocked}
              onClick={toggleShowUnlocked}
              icon={
                <PuzzleIconFromState
                  state="unlocked"
                  className="text-gray-400 group-hover/filter-button:text-white group-focus-visible/filter-button:text-white group-data-[selected=true]/filter-button:text-accent"
                />
              }
              className={cn("w-full", !showUnlocked && "text-gray-400")}
            >
              UNLOCKED
            </FilterButton>
            <FilterButton
              selected={showSolved}
              onClick={toggleShowSolved}
              icon={
                <PuzzleIconFromState
                  state="solved"
                  className="text-gray-400 group-hover/filter-button:text-white group-focus-visible/filter-button:text-white group-data-[selected=true]/filter-button:text-accent-green"
                />
              }
              className={cn("w-full", !showSolved && "text-gray-400")}
            >
              SOLVED
            </FilterButton>
          </div>
        </div>

        {/* Content */}
        <PuzzlesList
          state={filteredState}
          allPuzzlesVisible={
            (showUnlockable && showUnlocked && showSolved) ||
            (!showUnlockable && !showUnlocked && !showSolved)
          }
          search={search}
          teamState={teamState}
        />
      </div>
    </TeamStateProvider>
  );
}
